using System;using System.IO;using System.Web.Script.Serialization;
class TestRelease163Patch {
 static void Main(string[] args){var m=new JavaScriptSerializer().Deserialize<UpdateManifest>(File.ReadAllText(args[0]));var state=new JavaScriptSerializer().Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(Path.Combine(args[2],"BuildStatus.json")));Patch patch=null;foreach(var p in m.patches)if(p.fromVersion==Convert.ToString(state["version"]))patch=p;if(patch==null)throw new Exception("No matching source version");UpdateCore.CheckUrl(patch.url);UpdateCore.Apply(args[2],args[1],patch,s=>{});foreach(var f in patch.files)if(UpdateCore.Hash(UpdateCore.Inside(args[2],f.path))!=f.sha256)throw new Exception("Incorrect updated file");if(File.ReadAllText(Path.Combine(args[2],"Saved/Customization/design.txt"))!="personal design")throw new Exception("Changed logo data");if(File.ReadAllText(Path.Combine(args[2],"BenchyRacers/Config/BenchyEOS.ini"))!="private fixture")throw new Exception("Changed online config");Console.WriteLine("PASS: "+patch.fromVersion+" -> "+m.version+"; all target hashes and private fixtures preserved.");}
}
